import React, { useState, useEffect, useCallback } from 'react';
import Sidebar from './components/Sidebar';
import Player from './components/Player';
import SearchBar from './components/SearchBar';
import TrackRow from './components/TrackRow';
import HeroBanner from './components/HeroBanner';

const DEFAULT_ARTIST = 'coldplay';
const PROXY = 'https://corsproxy.io/?';
const API_BASE = 'https://www.theaudiodb.com/api/v1/json/123';

function apiUrl(path) {
  return `${PROXY}${encodeURIComponent(`${API_BASE}/${path}`)}`;
}
async function apiFetch(path) {
  const res = await fetch(apiUrl(path));
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}
async function fetchTracks(artist) {
  const data = await apiFetch(`searchtrack.php?s=${encodeURIComponent(artist)}`);
  return data.track || [];
}
async function fetchArtistInfo(artist) {
  const data = await apiFetch(`search.php?s=${encodeURIComponent(artist)}`);
  return data.artists?.[0] || null;
}
async function fetchAlbums(artist) {
  const data = await apiFetch(`searchalbum.php?s=${encodeURIComponent(artist)}`);
  return data.album || [];
}

export default function App() {
  const [activeNav, setActiveNav] = useState('home');
  const [tracks, setTracks] = useState([]);
  const [albums, setAlbums] = useState([]);
  const [artistInfo, setArtistInfo] = useState(null);
  const [currentTrack, setCurrentTrack] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [showAllTracks, setShowAllTracks] = useState(false);
  const [selectedAlbum, setSelectedAlbum] = useState(null);

  const loadArtist = useCallback(async (artist) => {
    setLoading(true);
    setError(null);
    setTracks([]);
    setArtistInfo(null);
    setAlbums([]);
    setSelectedAlbum(null);
    setShowAllTracks(false);
    try {
      const [t, a, al] = await Promise.all([
        fetchTracks(artist).catch(() => []),
        fetchArtistInfo(artist).catch(() => null),
        fetchAlbums(artist).catch(() => []),
      ]);
      if (!t.length && !a) {
        setError(`No results for "${artist}". Try: Coldplay, Adele, Radiohead, Daft Punk.`);
      } else {
        setTracks(t);
        setArtistInfo(a);
        setAlbums(al);
      }
    } catch (e) {
      setError('Could not reach the music database. Please try again.');
    }
    setLoading(false);
  }, []);

  useEffect(() => { loadArtist(DEFAULT_ARTIST); }, [loadArtist]);

  function playTrack(track) {
    setCurrentTrack({
      name: track.strTrack,
      artist: track.strArtist,
      thumb: track.strTrackThumb || track.strAlbumThumb,
      preview: track.strMusicVid || null,
    });
  }

  const filteredTracks = selectedAlbum
    ? tracks.filter(t => t.strAlbum === selectedAlbum)
    : tracks;
  const visibleTracks = showAllTracks ? filteredTracks : filteredTracks.slice(0, 8);

  return (
    <div style={styles.app}>
      <Sidebar active={activeNav} setActive={setActiveNav} />
      <div style={styles.main}>
        <div style={styles.content}>

          <div style={styles.header}>
            <SearchBar onSearch={loadArtist} loading={loading} />
            <div style={styles.headerRight}>
              <button style={styles.notifBtn}>🔔</button>
            </div>
          </div>

          {error && <div style={styles.error}>{error}</div>}

          {loading && (
            <div style={styles.loadingState}>
              <div style={styles.loadingSpinner} />
              <span style={{ color: 'var(--muted)', fontSize: 14 }}>Loading music...</span>
            </div>
          )}

          {!loading && artistInfo && (
            <div style={styles.artistBanner}>
              {artistInfo.strArtistThumb && (
                <img src={artistInfo.strArtistThumb} alt={artistInfo.strArtist} style={styles.artistThumb} />
              )}
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={styles.artistGenre}>{artistInfo.strGenre || 'Music'}{artistInfo.strCountry ? ` · ${artistInfo.strCountry}` : ''}</div>
                <div style={styles.artistName}>{artistInfo.strArtist}</div>
                <div style={styles.artistBio}>{(artistInfo.strBiographyEN || '').slice(0, 220)}...</div>
              </div>
              <div style={styles.artistStats}>
                <div style={styles.stat}>
                  <span style={styles.statNum}>{tracks.length}</span>
                  <span style={styles.statLabel}>Tracks</span>
                </div>
                <div style={styles.stat}>
                  <span style={styles.statNum}>{albums.length}</span>
                  <span style={styles.statLabel}>Albums</span>
                </div>
              </div>
            </div>
          )}

          {!loading && !artistInfo && !error && <HeroBanner onPlay={() => {}} />}

          {/* TRACKS — always shown before albums */}
          {!loading && tracks.length > 0 && (
            <div style={styles.section}>
              <div style={styles.sectionHeader}>
                <h2 style={styles.sectionTitle}>
                  {selectedAlbum ? `📀 ${selectedAlbum}` : 'Tracks'}
                </h2>
                <span style={styles.count}>{filteredTracks.length} songs</span>
                {selectedAlbum && (
                  <button style={styles.clearFilter} onClick={() => { setSelectedAlbum(null); setShowAllTracks(false); }}>
                    ✕ Show all
                  </button>
                )}
              </div>
              <div style={styles.trackHeader}>
                <div style={{ width: 28 }}>#</div>
                <div style={{ width: 42 }} />
                <div style={{ flex: 1 }}>TITLE</div>
                <div style={{ width: 170 }}>ALBUM</div>
                <div style={{ width: 52, textAlign: 'right' }}>TIME</div>
                <div style={{ width: 32 }} />
              </div>
              {visibleTracks.map((t, i) => (
                <TrackRow
                  key={t.idTrack || i}
                  track={t}
                  index={i}
                  onPlay={() => playTrack(t)}
                  isPlaying={currentTrack?.name === t.strTrack}
                />
              ))}
              {filteredTracks.length > 8 && (
                <button style={styles.seeAll} onClick={() => setShowAllTracks(s => !s)}>
                  {showAllTracks ? '▲ Show less' : `▼ Show all ${filteredTracks.length} tracks`}
                </button>
              )}
            </div>
          )}

          {/* ALBUMS */}
          {!loading && albums.length > 0 && (
            <div style={styles.section}>
              <div style={styles.sectionHeader}>
                <h2 style={styles.sectionTitle}>Albums</h2>
                <span style={styles.count}>{albums.length} albums · click to filter tracks</span>
              </div>
              <div style={styles.albumGrid}>
                {albums.map((al, i) => {
                  const active = selectedAlbum === al.strAlbum;
                  return (
                    <div
                      key={al.idAlbum || i}
                      style={{ ...styles.albumCard, ...(active ? styles.albumCardActive : {}) }}
                      onClick={() => { setSelectedAlbum(s => s === al.strAlbum ? null : al.strAlbum); setShowAllTracks(false); }}
                    >
                      {al.strAlbumThumb
                        ? <img src={al.strAlbumThumb} alt={al.strAlbum} style={styles.albumThumb} />
                        : <div style={styles.albumThumbFallback}>{al.strAlbum?.[0] || '♪'}</div>
                      }
                      <div style={styles.albumName}>{al.strAlbum}</div>
                      <div style={styles.albumYear}>{al.intYearReleased || '—'}</div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {!loading && !tracks.length && !error && (
            <div style={styles.emptyState}>
              <div style={styles.emptyIcon}>♪</div>
              <div style={styles.emptyText}>Search for an artist to get started</div>
              <div style={styles.suggestions}>
                {['Coldplay', 'Adele', 'Radiohead', 'Daft Punk'].map(a => (
                  <button key={a} style={styles.suggBtn} onClick={() => loadArtist(a)}>{a}</button>
                ))}
              </div>
            </div>
          )}

        </div>
        <Player track={currentTrack} />
      </div>
    </div>
  );
}

